function hub(){stop();notice('');app.innerHTML=`<section class="wc-type-select"><p class="wc-label">CHOOSE YOUR WORLD CUP</p><h2 tabindex="-1">어떤 노래를 골라볼까요?</h2><p>함께 부른 노래도, 각자의 목소리로 남긴 노래도.</p><div class="wc-type-grid">${collections.map((c,i)=>`<button class="wc-type-card" data-worldcup="${E(c.id)}"><span class="wc-type-number">0${i+1}</span><span class="wc-label">${c.id==='solo'?'SOLO SONGS':'SEEYA SONGS'}</span><strong>${E(c.title)}</strong><span>${E(c.description)}</span><small>${c.candidates.length}곡 · ${c.rounds.map(n=>n+'강').join(' / ')}</small><b>이 월드컵 선택 →</b></button>`).join('')}</div><p class="wc-small">이어하기와 내 우승 기록은 월드컵별로 따로 저장됩니다.</p></section>`;focus();}
